solution.solution.cpp:
#include <cstddef>
#include <cstdint>
#include <cstdlib>
#include <cstring>
#include <vector>

enum class Problem { InvalidFree, DoubleFree, Underrun, Overrun, WriteAfterFree };
struct Report { Problem problem; int allocation; };

class DebugHeap
{
public:
    static constexpr std::uint8_t CLEAN{ 0xCD }, DEAD{ 0xDD }, GUARD{ 0xFD };
    static constexpr std::size_t GUARD_BYTES{ 4 };

    ~DebugHeap() { for (Block& b : blocks) std::free(b.raw); }

    void* allocate(std::size_t size)
    {
        auto* raw{ static_cast<std::uint8_t*>(std::malloc(GUARD_BYTES + size + GUARD_BYTES)) };
        if (!raw) return nullptr;
        std::memset(raw, GUARD, GUARD_BYTES);
        std::memset(raw + GUARD_BYTES, CLEAN, size);
        std::memset(raw + GUARD_BYTES + size, GUARD, GUARD_BYTES);
        blocks.push_back({ raw, size, ++counter, false });
        return raw + GUARD_BYTES;
    }

    void release(void* p)
    {
        Block* b{ find(p) };
        if (!b) { reports.push_back({ Problem::InvalidFree, 0 }); return; }
        if (b->freed) { reports.push_back({ Problem::DoubleFree, b->number }); return; }
        if (!all(b->raw, GUARD_BYTES, GUARD)) reports.push_back({ Problem::Underrun, b->number });
        if (!all(b->raw + GUARD_BYTES + b->size, GUARD_BYTES, GUARD)) reports.push_back({ Problem::Overrun, b->number });
        std::memset(b->raw + GUARD_BYTES, DEAD, b->size);
        b->freed = true;
    }

    void checkFreed()
    {
        for (const Block& b : blocks)
            if (b.freed && !all(b.raw + GUARD_BYTES, b.size, DEAD)) reports.push_back({ Problem::WriteAfterFree, b.number });
    }

    std::vector<int> leaks() const
    {
        std::vector<int> numbers;
        for (const Block& b : blocks) if (!b.freed) numbers.push_back(b.number);
        return numbers;
    }

    const std::vector<Report>& problems() const { return reports; }

    std::size_t bytesInUse() const
    {
        std::size_t total{ 0 };
        for (const Block& b : blocks) if (!b.freed) total += b.size;
        return total;
    }

private:
    struct Block { std::uint8_t* raw; std::size_t size; int number; bool freed; };
    std::vector<Block> blocks;
    std::vector<Report> reports;
    int counter{ 0 };

    Block* find(void* p)
    {
        for (Block& b : blocks) if (b.raw + GUARD_BYTES == p) return &b;
        return nullptr;
    }

    static bool all(const std::uint8_t* bytes, std::size_t n, std::uint8_t value)
    {
        for (std::size_t i{ 0 }; i < n; ++i) if (bytes[i] != value) return false;
        return true;
    }
};

unitTests:
static bool same(const std::vector<Report>& r, std::initializer_list<Report> want)
{
    if (r.size() != want.size()) return false;
    std::size_t i{ 0 };
    for (const Report& w : want) { if (r[i].problem != w.problem || r[i].allocation != w.allocation) return false; ++i; }
    return true;
}

TEST("fresh blocks and guards") {
    DebugHeap heap;
    auto* p{ static_cast<std::uint8_t*>(heap.allocate(6)) };
    CHECK(p != nullptr);
    for (int i{ 0 }; i < 6; ++i) CHECK_EQ(p[i], 0xCD);
    for (int i{ 1 }; i <= 4; ++i) { CHECK_EQ(p[-i], 0xFD); CHECK_EQ(p[5 + i], 0xFD); }
    CHECK_EQ(heap.bytesInUse(), 6u);
}
TEST("a clean free reports nothing and fills with DD") {
    DebugHeap heap;
    auto* p{ static_cast<std::uint8_t*>(heap.allocate(8)) };
    std::memset(p, 0x11, 8);
    heap.release(p);
    CHECK(heap.problems().empty());
    CHECK_EQ(p[0], 0xDD); CHECK_EQ(p[7], 0xDD);
    CHECK(heap.leaks().empty());
    CHECK_EQ(heap.bytesInUse(), 0u);
}
TEST("overrun and underrun") {
    DebugHeap heap;
    auto* a{ static_cast<std::uint8_t*>(heap.allocate(4)) };
    auto* b{ static_cast<std::uint8_t*>(heap.allocate(4)) };
    a[4] = 0;
    b[-1] = 0;
    heap.release(a);
    heap.release(b);
    CHECK(same(heap.problems(), { { Problem::Overrun, 1 }, { Problem::Underrun, 2 } }));
}
TEST("double and invalid frees") {
    DebugHeap heap;
    void* a{ heap.allocate(3) };
    int local{ 0 };
    heap.release(a);
    heap.release(a);
    heap.release(&local);
    CHECK(same(heap.problems(), { { Problem::DoubleFree, 1 }, { Problem::InvalidFree, 0 } }));
}
TEST("writes after free are caught") {
    DebugHeap heap;
    auto* a{ static_cast<std::uint8_t*>(heap.allocate(16)) };
    heap.allocate(2);
    heap.release(a);
    heap.checkFreed();
    CHECK(heap.problems().empty());
    a[10] = 42;
    heap.checkFreed();
    CHECK(same(heap.problems(), { { Problem::WriteAfterFree, 1 } }));
}
TEST("leaks") {
    DebugHeap heap;
    void* a{ heap.allocate(10) };
    heap.allocate(20);
    void* c{ heap.allocate(0) };
    heap.allocate(5);
    heap.release(a);
    heap.release(c);
    CHECK_EQ(heap.leaks(), (std::vector<int>{ 2, 4 }));
    CHECK_EQ(heap.bytesInUse(), 25u);
}

